    garment = '<path d="M239 144 L273 130 Q300 154 327 130 L361 144 L398 218 L355 240 L345 209 L337 338 L448 639 Q300 671 152 639 L263 338 L255 209 L245 240 L202 218Z" fill="url(#cloth)"/>'
