    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="600" height="760" viewBox="0 0 600 760" role="img" aria-labelledby="title desc"><title id="title">Synthetic {name} garment illustration</title><desc id="desc">Original geometric fashion study, not a photograph or verified garment.</desc><defs><linearGradient id="wall" x2="1" y2="1"><stop stop-color="{bg}"/><stop offset="1" stop-color="{shadow}"/></linearGradient><linearGradient id="cloth" x1="0" x2="1"><stop stop-color="{dark}"/><stop offset=".25" stop-color="{base}"/><stop offset=".49" stop-color="{light}"/><stop offset=".72" stop-color="{base}"/><stop offset="1" stop-color="{dark}"/></linearGradient><pattern id="stitch" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M10 4v12M4 10h12" stroke="{light}" stroke-width=".6" opacity=".45"/></pattern><filter id="soft"><feGaussianBlur stdDeviation="16"/></filter></defs><rect width="600" height="760" fill="url(#wall)"/><path d="M0 586L600 670V760H0Z" fill="{shadow}" opacity=".48"/><path d="M416 0H600V670L416 644Z" fill="{bg}" opacity=".34"/><path d="M58 0H107L375 645L314 636Z" fill="{light}" opacity=".13"/><ellipse cx="310" cy="686" rx="146" ry="19" fill="{dark}" opacity=".24" filter="url(#soft)"/><path d="M300 78v26M300 104L247 136H353Z" fill="none" stroke="{dark}" stroke-width="3" opacity=".65"/>{garment}<path d="M278 147Q300 185 322 147M282 180L277 327M317 181L323 327" fill="none" stroke="{dark}" stroke-width="1.3" opacity=".45"/><path d="M270 345Q263 451 207 626M286 352Q292 471 267 640M317 348Q310 479 328 641M333 345Q342 464 399 630" fill="none" stroke="{dark}" stroke-width="2" opacity=".25"/><path d="M266 203L334 203L334 329L266 329Z" fill="url(#stitch)" opacity=".65"/><path d="M262 337Q300 348 338 337" fill="none" stroke="{light}" stroke-width="3" opacity=".6"/><g fill="{light}" opacity=".9"><circle cx="300" cy="193" r="2"/><circle cx="300" cy="215" r="2"/><circle cx="300" cy="237" r="2"/></g><path d="M161 633Q300 656 439 633" fill="none" stroke="{light}" stroke-width="2" opacity=".45"/><text x="36" y="48" fill="{dark}" font-size="9" font-family="sans-serif" letter-spacing="3" opacity=".65">TARA / ILLUSTRATIVE STUDY</text><text x="564" y="714" fill="{dark}" text-anchor="end" font-size="9" font-family="sans-serif" letter-spacing="2" opacity=".65">SAMPLE {name.upper()}</text></svg>'''
